"""JSON schemas passed to Gemini and reused for local validation."""
STRING_LIST = {"type": "array", "items": {"type": "string"}}
SECTION = {"type": "object", "properties": {"name": {"type": "string"}, "description": {"type": "string"}, "source_excerpt": {"type": "string"}}, "required": ["name", "description", "source_excerpt"], "additionalProperties": False}
RISK = {"type": "object", "properties": {"original_excerpt": {"type": "string"}, "category": {"type": "string"}, "risk_level": {"enum": ["Low", "Medium", "High"]}, "plain_language": {"type": "string"}, "why_attention": {"type": "string"}, "source_location": {"type": "string"}}, "required": ["original_excerpt", "category", "risk_level", "plain_language", "why_attention", "source_location"], "additionalProperties": False}
STRUCTURE = {"type": "object", "properties": {"title": {"type": "string"}, "document_type": {"type": "string"}, "sections": {"type": "array", "items": SECTION}}, "required": ["title", "document_type", "sections"], "additionalProperties": False}
SUMMARY = {"type": "object", "properties": {"summary": {"type": "string"}, "important_obligations": STRING_LIST, "user_rights": STRING_LIST, "unclear_points": STRING_LIST}, "required": ["summary", "important_obligations", "user_rights", "unclear_points"], "additionalProperties": False}
CANDIDATES = {"type": "object", "properties": {"risks": {"type": "array", "items": RISK}}, "required": ["risks"], "additionalProperties": False}
VERIFICATION = {"type": "object", "properties": {"verified_risks": {"type": "array", "items": RISK}, "rejected_count": {"type": "integer"}, "verification_notes": STRING_LIST}, "required": ["verified_risks", "rejected_count", "verification_notes"], "additionalProperties": False}
FINAL = {"type": "object", "properties": {"title": {"type": "string"}, "document_type": {"type": "string"}, "sections": {"type": "array", "items": SECTION}, "summary": {"type": "string"}, "important_obligations": STRING_LIST, "user_rights": STRING_LIST, "unclear_points": STRING_LIST, "risks": {"type": "array", "items": RISK}, "disclaimer": {"type": "string"}}, "required": ["title", "document_type", "sections", "summary", "important_obligations", "user_rights", "unclear_points", "risks", "disclaimer"], "additionalProperties": False}
